    "categoryLabel": "Microsoft & Windows",
    "subCategory": "Windows 11 & Windows 10",
    "readTime": "4 min read",
    "author": {
      "name": "Kevin Stewart",
      "role": "Windows OS & Hardware Diagnostics Lead",
      "img": "assets/expert-29.png"
    },
